    const event = baseEnvelope({
      card: { scryfallId: "e6f2c1a4-2222-4a22-9e33-000000000002" },
      gameCardIndex: 0,
      seat: "1",
    });

    expect(() => assertValidatesAsSpineEvent(event)).not.toThrow();
  });

